"""Application-owned caution wording; never derived from an LLM medical assessment."""

CAUTION_BASE = (
    "The workout plan generated by this application is for educational and informational "
    "purposes only. It does not constitute medical advice, diagnosis, or treatment.\n\n"
    "Physical exercise is inherently strenuous and carries a risk of injury or adverse "
    "health events, including but not limited to muscle strains, joint damage, "
    "cardiovascular events, and heat-related illnesses.\n\n"
    "Consult a qualified healthcare professional before starting a new exercise program, "
    "particularly if you have an injury, medical condition, or concerning symptoms"
)
CAUTION_END = (
    "Listen to your body. If, at any time while exercising, you experience faintness, "
    "dizziness, pain, unusual shortness of breath, nausea, or significant discomfort, "
    "**stop exercising immediately** and seek emergency medical attention if necessary."
)


def caution_text(limitations: str | None = None) -> str:
    """Return the fixed caution, quoting user-supplied limitations without interpretation.

    The additional sentence is included only for non-blank input. No model-produced
    medical assessment is used. Markdown metacharacters are escaped for display.
    """
    import re

    suffix = "."
    if limitations and limitations.strip():
        original = limitations.strip()
        # Escape Markdown control characters without changing the displayed words.
        quoted = re.sub(r"([\\`*_{}\[\]<>!|])", r"\\\1", original)
        suffix += (" You have indicated the following injuries or limitations: "
                   + quoted + ".")
    return CAUTION_BASE + suffix + "\n\n" + CAUTION_END


MEDICAL_DISCLAIMER = caution_text()
